function padNumber(n, width) {
  const neg = n < 0;
  const digits = String(Math.abs(n));
  const total = digits.length + (neg ? 1 : 0);
  if (total >= width) return String(n);
  return (neg ? "-" : "") + "0".repeat(width - total) + digits;
}

