reference:
function mergeIntervals(intervals) {
  if (intervals.length === 0) return [];
  const ivs = intervals.map(iv => [iv[0], iv[1]]).sort((p, q) => p[0] - q[0]);
  const out = [ivs[0]];
  for (let i = 1; i < ivs.length; i++) {
    const last = out[out.length - 1];
    if (ivs[i][0] <= last[1]) {
      if (ivs[i][1] > last[1]) last[1] = ivs[i][1];
    } else {
      out.push(ivs[i]);
    }
  }
  return out;
}

