reference:
function intToBase(n, base) {
  if (n === 0) return "0";
  const digits = "0123456789abcdef";
  const neg = n < 0;
  let v = Math.abs(n);
  let out = "";
  while (v > 0) {
    out = digits[v % base] + out;
    v = Math.floor(v / base);
  }
  return (neg ? "-" : "") + out;
}

