function dayOfYear(y, m, d) {
  const isLeap = (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
  const dm = [31, isLeap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  let total = d;
  for (let i = 0; i < m - 1; i++) total += dm[i];
  return total;
}

