function longestUniqueSubstring(s) {
  const last = new Map();
  let left = 0, best = 0;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (last.has(ch) && last.get(ch) >= left) left = last.get(ch) + 1;
    last.set(ch, i);
    const len = i - left + 1;
    if (len > best) best = len;
  }
  return best;
}

