function sortByFrequency(nums) {
  const freq = new Map();
  for (const n of nums) freq.set(n, (freq.get(n) || 0) + 1);
  return nums.slice().sort((a, b) => {
    const df = freq.get(b) - freq.get(a);
    if (df !== 0) return df;
    return a - b;
  });
}

