function rotateMatrix(matrix) {
  if (matrix.length === 0) return [];
  const R = matrix.length, C = matrix[0].length;
  const out = [];
  for (let i = 0; i < C; i++) {
    const row = [];
    for (let j = 0; j < R; j++) row.push(matrix[R - 1 - j][i]);
    out.push(row);
  }
  return out;
}

