function compressRanges(nums) {
  if (nums.length === 0) return "";
  const parts = [];
  let start = nums[0], prev = nums[0];
  for (let i = 1; i <= nums.length; i++) {
    if (i < nums.length && nums[i] === prev + 1) {
      prev = nums[i];
      continue;
    }
    parts.push(start === prev ? String(start) : start + "-" + prev);
    if (i < nums.length) {
      start = nums[i];
      prev = nums[i];
    }
  }
  return parts.join(",");
}

