function topKFrequentWords(words, k) {
  if (k <= 0) return [];
  const freq = new Map();
  for (const w of words) freq.set(w, (freq.get(w) || 0) + 1);
  const distinct = Array.from(freq.keys());
  distinct.sort((a, b) => {
    const df = freq.get(b) - freq.get(a);
    if (df !== 0) return df;
    return a < b ? -1 : a > b ? 1 : 0;
  });
  return distinct.slice(0, k);
}

