function addDaysToDate(y, m, d, n) {
  function isLeap(yr) {
    return (yr % 4 === 0 && yr % 100 !== 0) || yr % 400 === 0;
  }
  function daysInMonth(yr, mo) {
    const dm = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    if (mo === 2 && isLeap(yr)) return 29;
    return dm[mo - 1];
  }
  for (let i = 0; i < n; i++) {
    d++;
    if (d > daysInMonth(y, m)) {
      d = 1;
      m++;
      if (m > 12) { m = 1; y++; }
    }
  }
  return [y, m, d];
}

