function parseCsvLine(line) {
  const fields = [];
  let cur = "";
  let i = 0;
  let inQuotes = false;
  while (i < line.length) {
    const ch = line[i];
    if (inQuotes) {
      if (ch === '"') {
        if (i + 1 < line.length && line[i + 1] === '"') {
          cur += '"';
          i += 2;
        } else {
          inQuotes = false;
          i++;
        }
      } else {
        cur += ch;
        i++;
      }
    } else {
      if (ch === '"') {
        inQuotes = true;
        i++;
      } else if (ch === ",") {
        fields.push(cur);
        cur = "";
        i++;
      } else {
        cur += ch;
        i++;
      }
    }
  }
  fields.push(cur);
  return fields;
}

scoring.tests:
test("simple fields", () => assertDeepEqual(parseCsvLine("a,b,c"), ["a", "b", "c"]));
test("quoted field with comma", () => assertDeepEqual(parseCsvLine('"a,b",c'), ["a,b", "c"]));
test("escaped quotes", () => assertDeepEqual(parseCsvLine('a,"he said ""hi""",z'), ["a", 'he said "hi"', "z"]));
test("empty line is one empty field", () => assertDeepEqual(parseCsvLine(""), [""]));
test("empty middle field", () => assertDeepEqual(parseCsvLine("a,,b"), ["a", "", "b"]));
test("only commas", () => assertDeepEqual(parseCsvLine(",,"), ["", "", ""]));
test("single quoted field", () => assertDeepEqual(parseCsvLine('"quoted"'), ["quoted"]));
test("quoted empty then plain", () => assertDeepEqual(parseCsvLine('"",x'), ["", "x"]));

