function isValidTopoOrder(graph, order) {
  const keys = Object.keys(graph);
  if (order.length !== keys.length) return false;
  const position = {};
  for (let i = 0; i < order.length; i++) {
    if (Object.prototype.hasOwnProperty.call(position, order[i])) return false;
    position[order[i]] = i;
  }
  for (const key of keys) {
    if (!Object.prototype.hasOwnProperty.call(position, key)) return false;
  }
  for (const u of keys) {
    for (const v of graph[u]) {
      if (position[u] >= position[v]) return false;
    }
  }
  return true;
}

