function countStairWays(n, steps) {
  const memo = new Map();
  function ways(remaining) {
    if (remaining === 0) return 1;
    if (memo.has(remaining)) return memo.get(remaining);
    let total = 0;
    for (const step of steps) {
      if (step <= remaining) total += ways(remaining - step);
    }
    memo.set(remaining, total);
    return total;
  }
  return ways(n);
}

