function countDigitDecodings(s) {
  const n = s.length;
  if (n === 0) return 1;
  const dp = new Array(n + 1).fill(0);
  dp[0] = 1;
  dp[1] = s[0] === "0" ? 0 : 1;
  for (let i = 2; i <= n; i++) {
    if (s[i - 1] !== "0") dp[i] += dp[i - 1];
    const two = parseInt(s.slice(i - 2, i), 10);
    if (s[i - 2] !== "0" && two >= 10 && two <= 26) dp[i] += dp[i - 2];
  }
  return dp[n];
}

